/* @lc app=leetcode id=3539 lang=kotlin */ class Solution { fun magicalSum(m: Int, k: Int, nums: IntArray): Int = 1_000_000_007L.let { M -> Array(m + 1) { LongArray(m + 1) }.also { c -> (0..m).forEach { i -> (0..i).forEach { j -> c[i][j] = if (j == 0 || j == i) 1L else (c[i - 1][j - 1] + c[i - 1][j]) % M } } }.let { C -> nums.fold(Array(m + 1) { Array(m + 1) { LongArray(k + 1) } }.also { it[0][0][0] = 1L }) { dp, x -> (0..m).runningFold(1L) { a, _ -> a * x % M }.let { pw -> Array(m + 1) { Array(m + 1) { LongArray(k + 1) } }.also { nd -> (0..m).forEach { cnt -> (0..m).forEach { cr -> (0..k).forEach { o -> if (dp[cnt][cr][o] != 0L) (0..m - cnt).forEach { f -> (cr + f).let { tot -> (o + tot % 2).let { no -> if (no <= k) nd[cnt + f][tot / 2][no] = (nd[cnt + f][tot / 2][no] + dp[cnt][cr][o] * C[m - cnt][f] % M * pw[f]) % M } } } } } } } } }.let { dp -> (0..m).sumOf { cr -> (0..k).filter { it + Integer.bitCount(cr) == k }.sumOf { dp[m][cr][it] } } % M }.toInt() } } }